	router.GET(baseURL+"/users", wrapper.SearchUsers)
	router.GET(baseURL+"/users/me", wrapper.GetProfile)
	router.PATCH(baseURL+"/users/me", wrapper.UpdateProfile)
	router.GET(baseURL+"/users/me/applications", wrapper.ListMyApplications)
	router.GET(baseURL+"/users/me/invitations", wrapper.ListMyInvitations)
	router.GET(baseURL+"/users/me/notifications", wrapper.ListNotifications)
	router.PUT(baseURL+"/users/me/notifications/:notification_id/read", wrapper.ReadNotification)
	router.GET(baseURL+"/users/me/teams", wrapper.ListMyTeams)
	router.GET(baseURL+"/users/me/tournaments", wrapper.ListMyTournaments)

